@Composable private fun TodayScreen(vm:MainViewModel,onDetail:(Long)->Unit,onPlaces:()->Unit,onRoutePlan:(Long)->Unit){val days by vm.days.collectAsState();val settings by vm.settings.collectAsState();val places by vm.places.collectAsState();val now=LiveTick();val open=days.firstOrNull{d->d.events.none{it.type==EventType.WORK_END}};val today=open?:days.firstOrNull{it.day.date==LocalDate.now().toString()};val closed=today?.events?.any{it.type==EventType.WORK_END}==true;val planFlow=remember(today?.day?.id){vm.repo.plans(today?.day?.id?:-1)};val plans by planFlow.collectAsState(initial=emptyList());val recommended=plans.filter{!it.visited}.sortedBy{it.sortHint?:Int.MAX_VALUE}.mapNotNull{plan->places.firstOrNull{it.id==plan.placeId}};val current=places.firstOrNull{it.id==settings.currentPlaceId};val ctx=LocalContext.current;var editEvent by remember{mutableStateOf<WorkEvent?>(null)};var manualType by remember{mutableStateOf<EventType?>(null)};var pendingClose by remember{mutableStateOf<Pair<EventType,Long>?>(null)};var expectedTripEnd by remember{mutableStateOf<Long?>(null)};val base=places.firstOrNull{it.active&&(it.type==PlaceType.BAKERY||it.type==PlaceType.HOME)};LaunchedEffect(today?.day?.id,recommended.map{it.id},current?.id,today?.events?.lastOrNull()?.type){expectedTripEnd=null;if(today?.events?.lastOrNull()?.type==EventType.TRIP_START&&base!=null){runCatching{val start=current?:base;val path=listOf(start)+recommended.filter{it.id!=start.id&&it.id!=base.id}+listOf(base);val unique=path.distinctBy{it.id};val matrix=roadMatrix(unique);val indexes=unique.mapIndexed{i,p->p.id to i}.toMap();val seconds=path.zipWithNext().sumOf{matrix.durations[indexes.getValue(it.first.id)][indexes.getValue(it.second.id)]};expectedTripEnd=System.currentTimeMillis()+(seconds*1000).toLong()}}};val permissions=rememberLauncherForActivityResult(ActivityResultContracts.RequestMultiplePermissions()){};fun service(id:Long,start:Boolean){val i=Intent(ctx,TrackingService::class.java).setActio