fault.FormatListNumbered,null,Modifier.size(28.dp));Spacer(Modifier.width(10.dp));Text("Mai megállók",fontWeight=FontWeight.Bold)}};if((recommended.isNotEmpty()||current!=null)&&!closed)item{RouteRecommendation(recommended,onPlaces,{today.day.id.let(onRoutePlan)},current)};item{RRCard(Modifier.fillMaxWidth()){events.forEach{e->WorkEventRow(e.type,e.timestamp,{editEvent=e},{editEvent=e})};val last=events.lastOrNull()?.type;if(last==EventType.TRIP_START)WorkEventRow(EventType.TRIP_END,null,{pendingClose=EventType.TRIP_END to System.currentTimeMillis()},{manualType=EventType.TRIP_END})else if(last!=EventType.WORK_END)AddTripRow{if(ContextCompat.checkSelfPermission(ctx,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)permissions.launch(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.POST_NOTIFICATIONS));vm.run{vm.repo.nextAction(today.day.id);service(today.day.id,true)}};if(last!=EventType.WORK_END)WorkEventRow(EventType.WORK_END,null,{pendingClose=EventType.WORK_END to System.currentTimeMillis()},{manualType=EventType.WORK_END})}};if(closed)item{PrimaryButton("Új munkakezdés"){start()}};item{VersionFooter()}}}}
