@Composable private fun EarningsScreen(vm:MainViewModel){
    val days by vm.days.collectAsState();val periods by vm.periods.collectAsState();val settings by vm.settings.collectAsState();val now=LiveTick()
    val activePeriod=periods.firstOrNull{it.endDate==null};val periodDays=days.filter{activePeriod==null||it.day.date>=activePeriod.startDate};val live=periodDays.any{d->d.events.none{it.type==EventType.WORK_END}};val sums=periodDays.map{it.summary(settings,now)};val lastDate=periodDays.maxOfOrNull{it.day.date}?:activePeriod?.startDate?:LocalDate.now().toString()
    LazyColumn(contentPadding=PaddingValues(horizontal=12.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
        item{ScreenTitle("Kereset")}
        item{RRCard(Modifier.fillMaxWidth()){Row(Modifier.padding(12.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.DateRange,null,tint=Navy);Spacer(Modifier.width(8.dp));Column{Text("Aktuális kereseti időszak",fontSize=10.sp,color=DarkGray);Text("${activePeriod?.startDate?:"–"} – $lastDate",fontWeight=FontWeight.Bold,fontSize=13.sp)}}}}
        item{RRCard(Modifier.fillMaxWidth()){Column(Modifier.fillMaxWidth().padding(22.dp),horizontalAlignment=Alignment.CenterHorizontally){Icon(Icons.Default.AccountBalanceWallet,null,tint=Green,modifier=Modifier.size(35.dp));Text(if(live)"Eddigi kereset (élő)" else "Időszaki kereset",fontSize=12.sp,color=DarkGray);Text(money(sums.sumOf{it.earnings}),fontSize=32.sp,fontWeight=FontWeight.Bold,color=Green);if(live)Text("Frissítve: ${time(now)}",fontSize=10.sp,color=DarkGray)}}}
        item{RRCard(Modifier.fillMaxWidth()){EarningsCard("Munkaidő",longDuration(sums.sumOf{it.workMillis}),Green,Icons.Default.Schedule);HorizontalDivider();EarningsCard("Óradíj",money(settings.hourlyRate),Orange,Icons.Default.Payments);HorizontalDivider();EarningsCard("Ledolgozott munkák","${periodDays.size}",Navy,Icons.Default.Work)}}
    }
}
@Composable private fun StatsScreen(vm:MainViewModel){val days by vm.days.collectAsState();val settings by vm.settings.collectAsState();var selected by remember{mutableIntStateOf(0)};val sums=days.sortedBy{it.day.date}.map{it.summary(settings)};val tabs=listOf("Munkaidő","Útidő","Távolság","Kereset");LazyColumn(contentPadding=PaddingValues(horizontal=12.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{ScreenTitle("Statisztika")};item{PeriodSelector()};item{TabRow(selectedTabIndex=selected,containerColor=Color.White){tabs.forEachIndexed{i,t->Tab(i==selected,{selected=i},text={Text(t,fontSize=11.sp)})}}};item{BarChartCard("Napi munkaidő (óra)",sums.map{it.workMillis/3600000f},Green)};item{BarChartCard("Napi útidő (óra)",sums.map{it.travelMillis/3600000f},Blue)};item{BarChartCard("Napi megtett távolság (km)",sums.map{it.distanceMeters.toFloat()/1000},Orange)}}}
@Composable private fun BarChartCard(title:String,values:List<Float>,color:Color){RRCard(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(title,color=color,fontWeight=FontWeight.Bold,fontSize=12.sp);Text("Átlag: ${if(values.isEmpty())0 else values.average().toInt()}",fontSize=10.sp,color=DarkGray)};Spacer(Modifier.height(8.dp));Canvas(Modifier.fillMaxWidth().height(115.dp)){val vals=(if(values.isEmpty())listOf(0f)else values.takeLast(31));val max=(vals.maxOrNull()?:1f).coerceAtLeast(1f);val gap=size.width/vals.size;repeat(4){i->val y=size.height*i/4;drawLine(Border,Offset(0f,y),Offset(size.width,y),1f)};vals.forEachIndexed{i,v->val h=size.height*v/max;drawLine(color,Offset(gap*(i+.5f),size.height),Offset(gap*(i+.5f),size.height-h),gap*.45f,StrokeCap.Square)}}}}}

@Composable private fun SettingsScreen(vm:MainViewModel,onPlaces:()->Unit,onPeriods:()->Unit,onCheckUpdates:()->Unit){
    val days by vm.days.collectAsState();val settings by vm.settings.collectAsState();val ctx=LocalContext.current
    var rateDialog by remember{mutableStateOf(false)};var summaryDialog by remember{mutableStateOf(false)};var reportDialog by remember{mutableStateOf(false)};var tripDialog by remember{mutableStateOf(false)};var backupDialog by remember{mutableStateOf(false)}
    val treePicker=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocumentTree()){uri->uri?.let{ctx.contentResolver.takePersistableUriPermission(it,Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION);val updated=settings.copy(backupDriveTreeUri=it.toString());vm.run{vm.repo.saveSettings(updated);BackupManager.schedule(ctx,updated)}}}
    val restorePicker=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){uri->uri?.let{vm.run{BackupManager.restore(ctx,it)}}}
    LazyColumn{item{ScreenTitle("Beállítások")};item{SettingsRow(Icons.Default.Place,"Megállók",Green,onPlaces)};item{SettingsRow(Icons.Default.GpsFixed,"Út indítása és lezárása",Orange){tripDialog=true}};item{SettingsRow(Icons.Default.CalendarMonth,"Elszámolási időszakok",Navy,onPeriods)};item{SettingsRow(Icons.Default.AccountBalanceWallet,"Óradíj és kereset",Blue){rateDialog=true}};item{SettingsRow(Icons.Default.Dashboard,"Főoldali összesítő",Blue){summaryDialog=true}};item{SettingsRow(Icons.Default.Email,"Jelentések és e-mail",Navy){reportDialog=true}};item{SettingsRow(Icons.Default.CloudUpload,"Biztonsági mentés",Navy){backupDialog=true}};item{SettingsRow(Icons.Default.FileDownload,"Adatok exportálása",DarkGray){DataExporter.csv(ctx,days,settings)}};item{SettingsRow(Icons.Default.SystemUpdate,"Új verzió keresése",Green,onCheckUpdates)};item{SettingsRow(Icons.Default.Info,"Névjegy",DarkGray){}}}
    if(backupDialog)BackupSettingsDialog(settings,{backupDialog=false},{updated->vm.run{vm.repo.saveSettings(updated);BackupManager.schedule(ctx,updated)}},{treePicker.launch(null)},{vm.run{BackupManager.create(ctx)}},{restorePicker.launch(arrayOf("application/zip","application/octet-stream"))})
    if(tripDialog)AlertDialog(onDismissRequest={tripDialog=false},title={Text("Útkezelés")},text={Column{Text("A pékség elhagyásakor automatikusan elindítja, visszaérkezéskor pedig lezárja az utat.",fontSize=13.sp,color=DarkGray);SettingSwitch("Automatikus GPS-alapú útkezelés",settings.automaticBakeryTrips){vm.run{vm.repo.saveSettings(settings.copy(automaticBakeryTrips=it))}}}},confirmButton={TextButton({tripDialog=false}){Text("Rendben")}})
    if(rateDialog)RateDialog(settings,{rateDialog=false}){vm.run{vm.repo.saveSettings(it)};rateDialog=false};if(summaryDialog)SummarySettingsDialog(settings,{summaryDialog=false}){vm.run{vm.repo.saveSettings(it)};summaryDialog=false};if(reportDialog)ReportDialog(settings,{reportDialog=false}){vm.run{vm.repo.saveSettings(it)};reportDialog=false}
}
