    var gate by remember{mutableStateOf(place.encryptedGateCode?:"")};var note by remember{mutableStateOf(place.note)}
    var radius by remember{mutableStateOf(place.recognitionRadiusMeters.toString())};var type by remember{mutableStateOf(place.type)};var active by remember{mutableStateOf(place.active)};var gpsConfirmed by remember{mutableStateOf(place.gpsManuallyConfirmed)};var confirmDelete by remember{mutableStateOf(false)}
    var keyPhoto by remember{mutableStateOf(place.photoPath)};var entrancePhoto by remember{mutableStateOf(place.entrancePhotoPath)}
    var pendingKeyPath by remember{mutableStateOf<String?>(null)};var pendingEntrancePath by remember{mutableStateOf<String?>(null)}
    fun newPhoto(prefix:String):Pair<Uri,String>{val dir=File(ctx.filesDir,"photos").apply{mkdirs()};val file=File(dir,"${prefix}_${System.currentTimeMillis()}.jpg");return FileProvider.getUriForFile(ctx,"${ctx.packageName}.files",file) to file.absolutePath}
    val keyCamera=rememberLauncherForActivityResult(ActivityResultContracts.TakePicture()){ok->if(ok)keyPhoto=pendingKeyPath}
    val entranceCamera=rememberLauncherForActivityResult(ActivityResultContracts.TakePicture()){ok->if(ok)entrancePhoto=pendingEntrancePath}
    val locationClient=remember{LocationServices.getFusedLocationProviderClient(ctx)}
    fun readLocation(){locationClient.getCurrentLocation(com.google.android.gms.location.Priority.PRIORITY_HIGH_ACCURACY,null).addOnSuccessListener{p->p?.let{lat=it.latitude.toString();lng=it.longitude.toString();gpsConfirmed=true}}}
    val locationPermission=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){if(it)readLocation()}
    Column(Modifier.verticalScroll(rememberScrollState()).padding(12.dp),verticalArrangement=Arrangement.spacedBy(9.dp)){
        ScreenTitle(if(place.id==0L)"Új megálló" else "Megálló módosítása")
        RRCard(Modifier.fillMaxWidth()){Row(Modifier.fillMaxWidth().padding(horizontal=14.dp,vertical=8.dp),verticalAlignment=Alignment.CenterVertically){Icon(if(active)Icons.Default.Visibility else Icons.Default.VisibilityOff,null,tint=if(active)Green else DarkGray);Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text(if(active)"Aktív megálló" else "Inaktív megálló",fontWeight=FontWeight.Bold);Text(if(active)"Megjelenik a túratervezésnél" else "Nem jelenik meg a túratervezésnél",fontSize=11.sp,color=DarkGray)};Switch(active,{active=it})}}
        Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){FilterChip(type==PlaceType.CLIENT,{type=PlaceType.CLIENT},{Text("Megálló")},leadingIcon={Icon(Icons.Default.Person,null)});FilterChip(type==PlaceType.FUEL,{type=PlaceType.FUEL},{Text("Tankolás")},leadingIcon={Icon(Icons.Default.LocalGasStation,null)});FilterChip(type==PlaceType.BAKERY||type==PlaceType.HOME,{type=PlaceType.BAKERY},{Text("Bázis")},leadingIcon={Icon(Icons.Default.Home,null)})}
        Field(name,{name=it},"Név");Field(address,{address=it},"Hivatalos cím")
        Row(horizontalArrangement=Arrangement.spacedBy(7.dp)){OutlinedTextField(lat,{lat=it},label={Text("GPS szélesség")},modifier=Modifier.weight(1f));OutlinedTextField(lng,{lng=it},label={Text("GPS hosszúság")},modifier=Modifier.weight(1f))}
        SecondaryButton("Jelenlegi koordináta kiolvasása"){if(ContextCompat.checkSelfPermission(ctx,Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)readLocation()else locationPermission.launch(Manifest.permission.ACCESS_FINE_LOCATION)}
        Row(verticalAlignment=Alignment.CenterVertically){Icon(if(gpsConfirmed)Icons.Default.GpsFixed else Icons.Default.GpsNotFixed,null,tint=if(gpsConfirmed)Green else Orange);Spacer(Modifier.width(8.dp));Text(if(gpsConfirmed)"GPS-koordináta manuálisan pontosítva" else "A GPS-koordináta még nincs manuálisan pontosítva",fontSize=12.sp,color=if(gpsConfirmed)Green else Orange)}
        SecondaryButton("Megnyitás térképen"){openMap(ctx,lat.toDoubleOrNull(),lng.toDoubleOrNull(),name,address)}
        Field(gate,{gate=it},"Kártyakód")
        PhotoButton("Kulcsfotó",keyPhoto!=null,Icons.Default.Key){val p=newPhoto("key");pendingKeyPath=p.second;keyCamera.launch(p.first)}
        PhotoButton("Bejáratfotó",entrancePhoto!=null,Icons.Default.DoorFront){val p=newPhoto("entrance");pendingEntrancePath=p.second;entranceCamera.launch(p.first)}
        Field(note,{note=it},"Megjegyzés");Field(radius,{radius=it.filter(Char::isDigit)},"Felismerési sugár (méter)")
        PrimaryButton("Mentés"){if(name.isNotBlank())onSave(place.copy(type=type,name=name,officialAddress=address,latitude=lat.toDoubleOrNull(),longitude=lng.toDoubleOrNull(),encryptedGateCode=gate.ifBlank{null},photoPath=keyPhoto,entrancePhotoPath=entrancePhoto,note=note,recognitionRadiusMeters=radius.toIntOrNull()?:20,active=active,gpsManuallyConfirmed=gpsConfirmed))}
        if(place.id!=0L&&(type==PlaceType.CLIENT||type==PlaceType.FUEL))TextButton({confirmDelete=true},Modifier.fillMaxWidth()){Icon(Icons.Default.Delete,null,tint=Color.Red);Spacer(Modifier.width(6.dp));Text("Megálló törlése",color=Color.Red)}
    }
    if(confirmDelete)AlertDialog(onDismissRequest={confirmDelete=false},title={Text("Megálló törlése")},text={Text("Biztosan törlöd ezt a megállót? A túratervekből is eltűnik.")},confirmButton={Button({onDelete(place)},colors=ButtonDefaults.buttonColors(containerColor=Color.Red)){Text("Törlés")}},dismissButton={TextButton({confirmDelete=false}){Text("Mégse")}})
}
@Composable private fun PhotoButton(label:String,saved:Boolean,icon:ImageVector,onClick:()->Unit){RRCard(Modifier.fillMaxWidth().clickable(onClick=onClick)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Icon(icon,null,tint=DarkGray);Text("  $label",Modifier.weight(1f),fontWeight=FontWeight.Medium);if(saved){Icon(Icons.Default.CheckCircle,"Fénykép elmentve",tint=Green);Spacer(Modifier.width(8.dp))};Icon(Icons.Default.CameraAlt,"Fénykép készítése",tint=Blue)}}}
@Composable private fun Field(value:String,onChange:(String)->Unit,label:String){OutlinedTextField(value,onChange,label={Text(label)},modifier=Modifier.fillMaxWidth(),shape=RoundedCornerShape(9.dp))}

@Composable private fun DayDetail(vm:MainViewModel,id:Long,onBack:()->Unit){val day by vm.repo.observeDay(id).collectAsState(initial=null);val settings by vm.settings.collectAsState();var edit by remember{mutableStateOf<WorkEvent?>(null)};var add by remember{mutableStateOf(false)};val d=day?:return;val summary=d.summary(settings);val points=d.trips.firstOrNull()?.let{vm.repo.points(it.id).collectAsState(initial=emptyList()).value}?:emptyList();val ctx=LocalContext.current;edit?.let{EventDialog(it,{edit=null},{vm.run{vm.repo.updateEvent(it)};edit=null},{vm.run{vm.repo.deleteEvent(it)};edit=null})};if(add)AddEventDialog({add=false}){t,ts->vm.run{vm.repo.addEvent(id,t,ts)};add=false};LazyColumn(contentPadding=PaddingValues(12.dp),verticalArrangement=Arrangement.spacedBy(9.dp)){item{Surface(color=Navy,shape=RoundedCornerShape(14.dp),modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(18.dp)){Text("Munkanapló",color=Color.White,fontSize=21.sp,fontWeight=FontWeight.Bold);Text(d.day.date,color=Color.White.copy(alpha=.75f),fontSize=14.sp)}}};item{SummaryCard(summary)};item{RRCard(Modifier.fillMaxWidth()){EarningsCard("Megtett távolság",String.format(Locale("hu"),"%.1f km",summary.distanceMeters/1000),Orange,Icons.Default.Route)}};item{Surface(color=Color(0xFFF0F4FA),shape=RoundedCornerShape(14.dp),border=BorderStroke(1.dp,Color(0xFFD7E1EF))){Column{d.events.sortedBy{it.timestamp}.forEach{e->WorkEventRow(e.type,e.timestamp){edit=e}}}}};item{SecondaryButton("+ Esemény hozzáadása"){add=true}};item{PrimaryButton(if(points.isEmpty())"Nincs rögzített útvonal" else "Útvonal megnyitása térképen"){if(points.isNotEmpty())openRoute(ctx,points)}}}}
@Composable private fun EventDialog(e:WorkEvent,onDismiss:()->Unit,onSave:(WorkEvent)->Unit,onDelete:()->Unit){var v by remember{mutableStateOf(Instant.ofEpochMilli(e.timestamp).atZone(ZoneId.systemDefault()).toLocalDateTime().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")))};val deletable=e.type!=EventType.WORK_END;AlertDialog(onDismissRequest=onDismiss,title={Text("Esemény szerkesztése")},text={OutlinedTextField(v,{v=it},label={Text("Dátum és idő")})},confirmButton={TextButton({runCatching{LocalDateTime.parse(v,DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli()}.getOrNull()?.let{onSave(e.copy(timestamp=it))}}){Text("Mentés")}},dismissButton={Row{if(deletable)TextButton(onDelete){Text("Törlés",color=Color.Red)};TextButton(onDismiss){Text("Mégse")}}})}
@Composable private fun ManualTimeDialog(type:EventType,onDismiss:()->Unit,onSave:(Long)->Unit){var v by remember{mutableStateOf(LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")))};val title=when(type){EventType.WORK_START->"Munkakezdés időpontja";EventType.TRIP_START->"Indulás időpontja";EventType.TRIP_END->"Visszaérkezés időpontja";EventType.WORK_END->"Munka vége időpontja"};AlertDialog(onDismissRequest=onDismiss,title={Text(title)},text={OutlinedTextField(v,{v=it},label={Text("Dátum és idő")})},confirmButton={TextButton({runCatching{LocalDateTime.parse(v,DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli()}.getOrNull()?.let(onSave)}){Text("Mentés")}},dismissButton={TextButton(onDismiss){Text("Mégse")}})}
@Composable private fun AddEventDialog(onDismiss:()->Unit,onSave:(EventType,Long)->Unit){var type by remember{mutableStateOf(EventType.TRIP_START)};AlertDialog(onDismissRequest=onDismiss,title={Text("Esemény hozzáadása")},text={Column{EventType.entries.filter{it!=EventType.WORK_START}.forEach{Row(Modifier.clickable{type=it},verticalAlignment=Alignment.CenterVertically){RadioButton(type==it,{type=it});Text(when(it){EventType.WORK_START->"Munkakezdés";EventType.TRIP_START->"Útra indulás";EventType.TRIP_END->"Visszaérkezés";EventType.WORK_END->"Munka vége"})}}}},confirmButton={TextButton({onSave(type,System.currentTimeMillis())}){Text("Hozzáadás")}},dismissButton={TextButton(onDismiss){Text("Mégse")}})}
